// Do the generated WebSocket frame builders and event table describe the socket?
//
// HaivenWsApi.h is generated by codegen/emit_ws.py from the AsyncAPI description
// and, like the session core, carries no engine types, so the whole of it is
// under an ordinary compiler here. What this pins is the frame each builder hands
// FSessionCore::Send, the reply it names, and the payload type of each event --
// including the OAuth identity-link events a game waits on after SSO.
#include "HaivenSessionCore.h"
#include "HaivenWsApi.h"
#include <iostream>
#include <string>
#include <vector>

namespace
{
	std::vector<std::string> Failures;

	void Check(const char* What, bool Condition)
	{
		if (!Condition)
		{
			Failures.emplace_back(What);
		}
	}
}

int main()
{
	using namespace Haiven::Ws;

	const std::string MessageJson = R"({"channelId":"c1","content":"hi"})";
	const FWsRequest Send = ChatSend(MessageJson);
	Check("chat.send carries its wire type", Send.Type == "chat.send");
	Check("and the payload unchanged", Send.PayloadJson == MessageJson);
	Check("naming the payload contract", Send.PayloadSchema == "ChatSendRequestV0");
	Check("and the reply it expects", Send.ReplyType == "chat.send" && Send.ReplySchema == "ChatMessageSubmissionV0");

	const FWsRequest Ping = TransportPing();
	Check("ping sends no payload", Ping.Type == "ping" && !Ping.PayloadJson.has_value());
	Check("and is answered by pong", Ping.ReplyType == Types::Pong);

	const FWsEvent* Linked = FindEvent("account.identity.linked");
	Check("the OAuth link event is routed", Linked != nullptr);
	Check("with its payload contract",
		Linked != nullptr && std::string(Linked->PayloadSchema) == "AccountIdentityLinkedV0");
	const FWsEvent* LinkFailed = FindEvent(Types::AccountIdentityLinkFailed);
	Check("and so is its failure",
		LinkFailed != nullptr && std::string(LinkFailed->PayloadSchema) == "AccountIdentityLinkFailedV0");
	const FWsEvent* Entitlements = FindEvent(Types::EntitlementsUpdated);
	Check("the entitlement refresh hint is routed",
		Entitlements != nullptr && std::string(Entitlements->PayloadSchema) == "EntitlementsUpdatedV0");
	const FWsEvent* Motd = FindEvent(Types::Motd);
	Check("the Message of the Day is routed", Motd != nullptr && std::string(Motd->PayloadSchema) == "MotdV0");
	Check("an unknown event is not an error, just unknown", FindEvent("entitlements.minted.later") == nullptr);
	Check("a request type is not an event", FindEvent(Types::ChatSend) == nullptr);

	// The builder feeds the hand-written session unchanged.
	std::vector<Haiven::FClientFrame> Written;
	int Next = 0;
	Haiven::FSessionCore Session(
		[&Written](const Haiven::FClientFrame& Frame) { Written.push_back(Frame); },
		[] { return std::string("token"); },
		[&Next] { return "rq-" + std::to_string(++Next); });
	Session.Opened();
	Session.Receive(Haiven::FServerFrame{"auth.success", std::string(""), true, std::nullopt, true, std::nullopt}, "{}");
	Session.Send(Send.Type, Send.PayloadJson);
	Check("the session writes the built frame after auth",
		Written.size() == 2 && Written[1].Type == "chat.send" && Written[1].PayloadJson == MessageJson);

	if (Failures.empty())
	{
		std::cout << "ok   C++ generated WebSocket frame builders" << std::endl;
		return 0;
	}

	for (const std::string& Failure : Failures)
	{
		std::cout << "FAIL " << Failure << std::endl;
	}

	return 1;
}
